import matplotlib.pyplot as plt
import numpy as np
import imageio.v2 as imageio  # Fixed to use modern imageio API cleanly
import os

# 1. Load the pose data generated by your C++ code
try:
    data = np.loadtxt('poses.csv', delimiter=',', skiprows=1)
    if data.ndim == 1:
        data = np.array([data])
except Exception as e:
    print(f"Error loading poses.csv: Make sure to run your C++ program first! Details: {e}")
    exit(1)

# 2. Set up the 3D plot with a fixed window size
fig = plt.figure(figsize=(8, 6))
ax = fig.add_subplot(projection='3d')

# Plot the poses from C++ data
for row in data:
    x, y, z, roll, pitch, yaw = row
    ax.scatter(x, y, z, color='red', s=120, label='Position')
    
    dx = np.cos(yaw)
    dy = np.sin(yaw)
    ax.quiver(x, y, z, dx, dy, 0.0, length=0.8, color='blue', normalize=True, linewidth=2, label='Heading (Yaw)')

# Graph styling and bounds
ax.set_xlabel('X Axis')
ax.set_ylabel('Y Axis')
ax.set_zlabel('Z Axis')
ax.set_xlim([-1, 3])
ax.set_ylim([-1, 3])
ax.set_zlim([0, 2])
ax.set_title('Simple3D - Rotating 3D View')

# 3. Capture frames for the GIF with strict size locking
frames = []
temp_filename = 'temp_frame.png'

print("Generating frames for GIF animation...")
for angle in range(0, 360, 10):
    ax.view_init(elev=30, azim=angle)
    
    # dpi=100 and bbox_inches='tight' ensure exact matching pixel sizes
    plt.savefig(temp_filename, dpi=100, format='png')
    
    # Read the image frame back
    frame = imageio.imread(temp_filename)
    frames.append(frame)

# Clean up temporary image file
if os.path.exists(temp_filename):
    os.remove(temp_filename)

# 4. Save frames as an animated GIF
output_gif = 'simple3d_animation.gif'
imageio.mimsave(output_gif, frames, fps=10)
print(f"Success! Animation saved as '{output_gif}' in your project folder.")